{
  "focus_areas": [
    "Lower fasting glucose and HbA1c risk",
    "Improve LDL and total cholesterol",
    "Lower triglycerides",
    "Heart-healthy vegetarian meals with portion control",
    "Regular walking and consistent sleep"
  ],
  "diet_recommendations": [
    {
      "item": "At breakfast, replace white bread, maida upma or a large rice portion with 2 small jowar or bajra rotis plus 1 katori cooked moong sprouts or low-fat paneer sabzi; eat breakfast within 1-2 hours of waking.",
      "rationale": "Millets with sprouts or low-fat paneer give slow-release carbohydrate and protein, which may help lower fasting glucose.",
      "linked_biomarker": "glucose_fasting"
    },
    {
      "item": "Build lunch and dinner as 1 katori dal + 1 katori seasonal sabzi + 1 small millet roti or 1/2 katori brown rice; keep a 3-4 hour gap between meals and finish dinner by 8:00-8:30 pm.",
      "rationale": "Fibre and protein with controlled carbohydrate portions support steadier post-meal glucose and lower HbA1c.",
      "linked_biomarker": "hba1c"
    },
    {
      "item": "Have 1 katori cooked oats or barley porridge 4 times a week at breakfast, and eat 1 katori salad before lunch and dinner.",
      "rationale": "Soluble fibre from oats, barley and vegetables helps lower LDL cholesterol.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Cook with 2-3 teaspoons total of mustard, groundnut or rice bran oil per day across meals; choose toned or low-fat milk and low-fat paneer; use 4-5 almonds and 1 walnut as a snack instead of fried snacks.",
      "rationale": "Replacing saturated fat from butter, ghee, cream and deep-fried foods with unsaturated oils and nuts helps lower total cholesterol.",
      "linked_biomarker": "total_cholesterol"
    },
    {
      "item": "At dinner choose 1 katori dal or sprouts + 1-2 katoris seasonal sabzi + 1 small millet roti; avoid eating rice and roti together at the same meal and avoid a heavy late-night meal.",
      "rationale": "A lower refined-carbohydrate load and avoiding late heavy meals can help reduce triglycerides.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "For snacks use 1 medium guava or apple or 1 katori unsalted roasted chana instead of biscuits, sweets or fruit juice; drink water, unsweetened tea or unsweetened buttermilk.",
      "rationale": "Avoiding sugary snacks and drinks reduces glucose spikes and triglyceride production.",
      "linked_biomarker": "triglycerides"
    }
  ],
  "foods_to_avoid": [
    "Sugar, jaggery, honey, sweets, mithai and sweetened drinks including fruit juice and sugary tea or coffee",
    "White bread, maida bakery items, refined-flour snacks and large portions of white rice at one meal",
    "Deep-fried foods such as samosa, pakora, puri and chips; limit ghee, butter, cream and full-fat paneer",
    "Processed and packaged snacks, sweetened breakfast cereals and fast food",
    "Alcohol, if consumed, because it can raise triglycerides"
  ],
  "activity": "Aim for 30 minutes of brisk walking on 5 days a week, plus a 10-minute easy walk after lunch and dinner. Start slowly if you are not used to exercise, follow your doctor's advice, and stop and seek medical care for chest pain, breathlessness or dizziness.",
  "sleep": "Target 7-8 hours of sleep with a consistent bedtime. Avoid screens for 45 minutes before bed, and keep dinner at least 2-3 hours before sleeping.",
  "retest_in_weeks": 12
}
